import{_ as e,o as l,c as a,ag as r}from"./chunks/framework.DXGyWiRo.js";const f=JSON.parse('{"title":"🧊 iCheat 使用教程","description":"","frontmatter":{},"headers":[],"relativePath":"cs2/free icheat.md","filePath":"cs2/free icheat.md"}'),o={name:"cs2/free icheat.md"};function n(s,t,i,d,g,h){return l(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="🧊-icheat-使用教程" tabindex="-1">🧊 iCheat 使用教程 <a class="header-anchor" href="#🧊-icheat-使用教程" aria-label="Permalink to &quot;🧊 iCheat 使用教程&quot;">​</a></h1><p>欢迎使用 iCheat。请严格按照以下流程进行下载与安装。</p><div class="warning custom-block"><p class="custom-block-title">🛡️ 安全提示</p><p><strong>这不是病毒文件！</strong> 作弊产品需要调用系统高权限内存进行读写，因此防护软件会误报。运行前请务必<strong>关闭所有杀毒软件</strong>或将其加入白名单。 P.S：报错是正常！！！</p></div><hr><h3 id="📥-获取与安装" tabindex="-1">📥 获取与安装 <a class="header-anchor" href="#📥-获取与安装" aria-label="Permalink to &quot;📥 获取与安装&quot;">​</a></h3><ol><li><strong>访问官网：</strong> 前往 <a href="https://icheat.io/free-cs2-cheats/" target="_blank" rel="noreferrer">icheat.io</a> 获取最新 Pin 码并下载注入器。</li><li><strong>解压文件：</strong> 下载 <code>DOWNLOAD.zip</code> 后解压，找到 <code>undetek-v??.??.exe</code>。</li><li><strong>管理员运行：</strong> 右键点击程序，选择 <strong>[以管理员身份运行]</strong>。</li><li><strong>注入启动：</strong> 进入游戏大厅后，输入你获取的 Pin 码即可完成注入。</li><li><strong>菜单开关：</strong> 按下键盘上的 <strong><code>Del</code></strong> 键可开启/隐藏菜单。</li></ol><hr><h3 id="📺-视频教学" tabindex="-1">📺 视频教学 <a class="header-anchor" href="#📺-视频教学" aria-label="Permalink to &quot;📺 视频教学&quot;">​</a></h3><p>如果看不明白，可以参考以下视频操作： <a href="https://youtu.be/gTIYmayejqs" target="_blank" rel="noreferrer">点击观看视频教程</a></p><hr><h3 id="⌨️-按键绑定技巧-重要" tabindex="-1">⌨️ 按键绑定技巧 (重要) <a class="header-anchor" href="#⌨️-按键绑定技巧-重要" aria-label="Permalink to &quot;⌨️ 按键绑定技巧 (重要)&quot;">​</a></h3><p>绑定按键时请遵循以下步骤：</p><ol><li>先 <strong>按住</strong> 小键盘上的方向键 <strong><code>→</code></strong>。</li><li>同时 <strong>按下</strong> 你想要绑定的目标按键。</li></ol><blockquote><p><em>注意：绑定后显示的是该按键对应的独立数字编码，这是正常现象。</em></p></blockquote><hr><h3 id="📖-功能与开关翻译" tabindex="-1">📖 功能与开关翻译 <a class="header-anchor" href="#📖-功能与开关翻译" aria-label="Permalink to &quot;📖 功能与开关翻译&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">英文选项</th><th style="text-align:left;">中文含义</th><th style="text-align:left;">详细说明</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Aimbot</strong></td><td style="text-align:left;">瞄准开关</td><td style="text-align:left;">自动瞄准总开关</td></tr><tr><td style="text-align:left;"><strong>Key</strong></td><td style="text-align:left;">自瞄按键</td><td style="text-align:left;">设置自瞄触发键</td></tr><tr><td style="text-align:left;"><strong>Smooth</strong></td><td style="text-align:left;">自瞄平滑度</td><td style="text-align:left;">数值越低，拉枪速度越快</td></tr><tr><td style="text-align:left;"><strong>Trigger</strong></td><td style="text-align:left;">自动扳机</td><td style="text-align:left;">准星对准敌人时自动开火</td></tr><tr><td style="text-align:left;"><strong>Spotted</strong></td><td style="text-align:left;">可视侦测</td><td style="text-align:left;">开启后，仅对视野内敌人生效 (防隔墙)</td></tr><tr><td style="text-align:left;"><strong>Esp</strong></td><td style="text-align:left;">透视功能</td><td style="text-align:left;">墙后敌人位置显示</td></tr><tr><td style="text-align:left;"><strong>Beefmode</strong></td><td style="text-align:left;">恶搞模式</td><td style="text-align:left;">在角色头上显示恶搞图片</td></tr></tbody></table><p><strong>状态显示：</strong></p><ul><li><span style="color:#4CAF50;font-weight:bold;">On (绿色)</span>：功能已开启</li><li><span style="color:#F44336;font-weight:bold;">Off (红色)</span>：功能已关闭</li></ul>',19)])])}const p=e(o,[["render",n]]);export{f as __pageData,p as default};
